-- ============================================================================
-- Tarbiyah Institute — the API roles could not use the number sequences
-- ============================================================================
-- students.student_number and certificates.certificate_number are generated by
-- column defaults calling nextval(). A role needs USAGE on a sequence to
-- evaluate that default, and the RLS migration granted table privileges without
-- ever granting the sequences.
--
-- So every insert through the Data API failed with "permission denied for
-- sequence student_number_seq" — enrolling a student, and issuing a
-- certificate. It stayed hidden because every row until now was created over a
-- superuser connection, which ignores grants.
--
-- anon is deliberately excluded: it has no insert rights on either table.
-- ============================================================================

grant usage on sequence public.student_number_seq     to authenticated;
grant usage on sequence public.certificate_number_seq to authenticated;
